13	// This is normally handled using decorations in the
14	// `NumberedListIndexingDecorationPlugin`. This does not run when exporting, so
15	// we have to add the necessary HTML attributes ourselves.
16	const addIndexToNumberedListItems = (element: HTMLElement) => {
17	  const numberedListItems = element.querySelectorAll(
18	    '[data-content-type="numberedListItem"]',
19	  );
20	  numberedListItems.forEach((numberedListItem) => {
21	    const prevNumberedListItem = numberedListItem
22	      .closest(".bn-block-outer")
23	      ?.previousElementSibling?.querySelector(
24	        '[data-content-type="numberedListItem"]',
25	      );
26	
27	    if (!prevNumberedListItem) {
28	      numberedListItem.setAttribute(
29	        "data-index",
30	        numberedListItem.getAttribute("data-start") || "1",
31	      );
32	    } else {
33	      const prevNumberedListItemIndex =
34	        prevNumberedListItem.getAttribute("data-index");
35	      numberedListItem.setAttribute(
36	        "data-index",
37	        (parseInt(prevNumberedListItemIndex || "0") + 1).toString(),
38	      );
