90	// `columnResizing` extension. This extension doesn't run when exporting to
91	// HTML, so we have to add this manually. This adds the correct padding to
92	// tables.
93	const addTableWrappers = (element: HTMLElement) => {
94	  const tables = element.querySelectorAll('[data-content-type="table"] table');
95	  tables.forEach((table) => {
96	    const tableWrapper = document.createElement("div");
97	    tableWrapper.className = "tableWrapper";
