112	const addTrailingBreakToEmptyInlineContent = (element: HTMLElement) => {
113	  const emptyInlineContent = element.querySelectorAll(
114	    ".bn-inline-content:empty",
115	  );
116	  emptyInlineContent.forEach((inlineContent) => {
117	    // We actually use a `span` instead of a `br` to avoid potential false
118	    // positives when parsing.
119	    const trailingBreak = document.createElement("span");
120	    trailingBreak.className = "ProseMirror-trailingBreak";
121	    trailingBreak.setAttribute("style", "display: inline-block;");
122	
123	    inlineContent.appendChild(trailingBreak);
124	  });
