129	// Used to serialize BlockNote blocks and ProseMirror nodes to HTML without
130	// losing data. Blocks are exported using the `toInternalHTML` method in their
131	// `blockSpec`.
132	//
133	// The HTML created by this serializer is the same as what's rendered by the
134	// editor to the DOM. This means that it retains the same structure as the
135	// editor, including the `blockGroup` and `blockContainer` wrappers. This also
136	// means that it can be converted back to the original blocks without any data
137	// loss.
138	export const createInternalHTMLSerializer = <
139	  BSchema extends BlockSchema,
140	  I extends InlineContentSchema,
141	  S extends StyleSchema,
142	>(
143	  schema: Schema,
144	  editor: BlockNoteEditor<BSchema, I, S>,
145	) => {
146	  const serializer = DOMSerializer.fromSchema(schema);
147	
148	  // Set of transforms to run on the output HTML element after serializing
149	  // blocks. These are used to add HTML elements, attributes, or class names
150	  // which would normally be done by extensions and plugins. Since these don't
151	  // run when converting blocks to HTML, tranforms are used to mock their
152	  // functionality so that the rendered HTML looks identical to that of a live
153	  // editor.
154	  const transforms: ((element: HTMLElement) => HTMLElement)[] = [
155	    addIndexToNumberedListItems,
156	    makeCheckListItemsReadOnly,
157	    forceToggleBlocksShow,
158	    addTableMinCellWidths,
159	    addTableWrappers,
160	    addTrailingBreakToEmptyInlineContent,
161	  ];
162	
163	  return {
164	    serializeBlocks: (
165	      blocks: PartialBlock<BSchema, I, S>[],
166	      options: { document?: Document },
167	    ) => {
168	      let element = serializeBlocksInternalHTML(
169	        editor,
170	        blocks,
171	        serializer,
172	        options,
173	      );
174	
175	      for (const transform of transforms) {
176	        element = transform(element);
177	      }
178	
179	      return element.outerHTML;
180	    },
181	  };
182	};
